var leagues = sqliteTable("leagues", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull().unique(),
  slug: text("slug").notNull().unique(),
  logoUrl: text("logo_url")
});
var teams = sqliteTable("teams", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  leagueId: integer("league_id").notNull().references(() => leagues.id),
  name: text("name").notNull(),
  region: text("region"),
  slug: text("slug").notNull().unique(),
  primaryColor: text("primary_color"),
  secondaryColor: text("secondary_color"),
  logoUrl: text("logo_url"),
  yahooRosterUrl: text("yahoo_roster_url")
});
var players = sqliteTable("players", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  teamId: integer("team_id").notNull().references(() => teams.id),
  name: text("name").notNull(),
  displayName: text("display_name").notNull(),
  number: integer("number").notNull(),
  type: text("type").default("Current"),
  group: text("group").default("Football"),
  isActive: integer("is_active", { mode: "boolean" }).default(true)
});
var rosterChanges = sqliteTable("roster_changes", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  teamId: integer("team_id").notNull().references(() => teams.id),
  playerName: text("player_name").notNull(),
  playerNumber: integer("player_number").notNull(),
  changeType: text("change_type").notNull(),
  // new, updated, removed
  source: text("source").default("csv"),
  // csv, yahoo
  status: text("status").default("pending"),
  // pending, approved, rejected
  diffData: text("diff_data"),
  // Serialized JSON string
  detectedAt: text("detected_at")
  // ISO timestamp
});
var mockupTemplates = sqliteTable("mockup_templates", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  teamId: integer("team_id").references(() => teams.id),
  name: text("name").notNull(),
  colorVariant: text("color_variant"),
  originalImageUrl: text("original_image_url"),
  fontConfig: text("font_config"),
  // Serialized JSON string
  canvasJson: text("canvas_json"),
  // Serialized JSON string
  backgroundColor: text("background_color").default("#e5e7eb")
});
var fonts = sqliteTable("fonts", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull(),
  fileUrl: text("file_url").notNull(),
  previewUrl: text("preview_url"),
  category: text("category").default("NFL"),
  teamId: integer("team_id").references(() => teams.id),
  jerseyType: text("jersey_type")
  // Home, Away, Alternate, None
});
var patches = sqliteTable("patches", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull(),
  imageUrl: text("image_url").notNull(),
  width: integer("width"),
  height: integer("height")
});
var bulkJobs = sqliteTable("bulk_jobs", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  status: text("status").default("pending"),
  // pending, running, completed, failed
  totalItems: integer("total_items").default(0),
  completedItems: integer("completed_items").default(0),
  failedItems: integer("failed_items").default(0),
  storeTargets: text("store_targets"),
  // Serialized JSON list
  seoTemplate: text("seo_template"),
  // Serialized JSON object
  createdAt: text("created_at"),
  // ISO timestamp
  completedAt: text("completed_at")
  // ISO timestamp
});
var bulkJobItems = sqliteTable("bulk_job_items", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  jobId: integer("job_id").notNull().references(() => bulkJobs.id),
  playerId: integer("player_id").notNull().references(() => players.id),
  mockupTemplateId: integer("mockup_template_id").notNull().references(() => mockupTemplates.id),
  gender: text("gender").notNull(),
  // Men, Women, Youth
  color: text("color"),
  status: text("status").default("pending"),
  // pending, generating, uploading, done, failed
  generatedImageUrl: text("generated_image_url"),
  productTitle: text("product_title"),
  productDescription: text("product_description"),
  productCategory: text("product_category"),
  storeProductIds: text("store_product_ids"),
  // Serialized JSON map
  errorMessage: text("error_message")
});
var stores = sqliteTable("stores", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull(),
  platform: text("platform").notNull(),
  // woocommerce, shopbase
  url: text("url").notNull(),
  apiKey: text("api_key").notNull(),
  apiSecret: text("api_secret").notNull(),
  isActive: integer("is_active", { mode: "boolean" }).default(true),
  lastSyncedAt: text("last_synced_at"),
  createdAt: text("created_at")
});
var users = sqliteTable("users", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  username: text("username").notNull().unique(),
  hashedPassword: text("hashed_password").notNull(),
  createdAt: text("created_at")
});
var orders = sqliteTable("orders", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  storeId: text("store_id"),
  orderId: text("order_id"),
  orderName: text("order_name"),
  customerName: text("customer_name").notNull(),
  customerAddress: text("customer_address").notNull(),
  customerEmail: text("customer_email"),
  productName: text("product_name").notNull(),
  productImage: text("product_image"),
  quantity: integer("quantity").default(1),
  variant: text("variant"),
  variantValue: text("variant_value"),
  revenue: real("revenue").default(0),
  cost: real("cost").default(0),
  shippingStatus: text("shipping_status").default("placed"),
  // placed, in transit, delivered, incident
  trackingNumber: text("tracking_number"),
  emailSent: integer("email_sent", { mode: "boolean" }).default(false),
  trackingEmailSent: integer("tracking_email_sent", { mode: "boolean" }).default(false),
  createdAt: text("created_at"),
  syncedAt: text("synced_at")
});
var syncedProducts = sqliteTable("synced_products", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  name: text("name").notNull(),
  platformProductId: text("platform_product_id"),
  platform: text("platform").notNull(),
  // woocommerce, shopbase, astro
  imageUrl: text("image_url"),
  price: real("price").default(0),
  sku: text("sku"),
  createdAt: text("created_at")
});
var tickets = sqliteTable("tickets", {
  id: integer("id").primaryKey({ autoIncrement: true }),
  customerName: text("customer_name").notNull(),
  customerEmail: text("customer_email").notNull(),
  subject: text("subject").notNull(),
  message: text("message").notNull(),
  status: text("status").default("open"),
  // open, pending, resolved, spam, snoozed
  replies: text("replies").default("[]"),
  // Serialized JSON string of replies
  recipientEmail: text("recipient_email"),
  tags: text("tags").default(""),
  snoozedUntil: text("snoozed_until"),
  createdAt: text("created_at")
});

